// Monat und Aktion bestimmen.
//   Schedule (2. des Monats, nach der Proformarechnung aus Workflow 05 am 1.):
//     Datei für den Vormonat erzeugen ("create").
//   Webhook, Body z.B. {"month": "2026-09", "action": "preview"}:
//     preview  Vorschau mit Prüfbericht, schreibt nichts (Standard)
//     create   Datei erzeugen und speichern. Gibt es sie schon, kommt dieselbe
//              Datei erneut; "regenerate": true erzeugt sie neu, solange der
//              Import nicht bestätigt ist
//     confirm  nach dem Import in Lexoffice: Monat als importiert markieren
//   "proforma_number" nur angeben, wenn die Proformarechnung des Monats nicht
//   aus Workflow 05 stammt (z.B. vor etsy_rc.start_date von Hand geschrieben).
// Alle fachlichen Prüfungen (abgeschlossener Monat, Stichtag, Summen,
// Proformarechnung) macht die Datenbank, siehe Migration 004.
const yearMonth = (d) => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit',
}).format(d);                                   // "2026-10"

const manual = $('Webhook: manuell').isExecuted;
let req = {};
if (manual) {
  const w = $('Webhook: manuell').first().json;
  req = { ...(w.query ?? {}), ...(w.body ?? {}) };
}

let month = req.month != null ? String(req.month).trim() : '';
if (!month) {
  const [y, m] = yearMonth(new Date()).split('-').map(Number);
  month = m === 1 ? `${y - 1}-12` : `${y}-${String(m - 1).padStart(2, '0')}`;
}
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
  throw new Error(`Ungültiger Monat '${month}' – erwartet wird YYYY-MM`);
}
const action = manual ? String(req.action ?? 'preview').trim().toLowerCase() : 'create';
if (!['preview', 'create', 'confirm'].includes(action)) {
  throw new Error(`Unbekannte action '${action}' – erlaubt sind preview, create, confirm`);
}

return [{
  json: {
    month,
    action,
    regenerate: req.regenerate === true || String(req.regenerate ?? '').toLowerCase() === 'true',
    proforma_number: req.proforma_number != null ? String(req.proforma_number).trim() : '',
  },
}];

// Mail mit dem Prüfbericht. Die CSV hängt nur an, wenn sie (noch) importiert
// werden soll. Eine Vorschau heißt *_VORSCHAU.csv: sie ist nicht gespeichert,
// also nicht importieren – erst "create" macht daraus die Datei für Lexoffice.
const { result: r, mail } = $input.first().json;
if (!mail?.from || !mail?.to) {
  throw new Error("Mail-Adressen fehlen in app_config (scope 'mail'): from, to");
}

const label = r.label ?? r.month;
const eur = (n) => Number(n ?? 0).toLocaleString('de-DE',
  { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const lines = r.ok && r.line_count != null ? ` – ${r.line_count} Zeilen, Summe ${eur(r.line_sum)}` : '';
const subject = {
  preview:           `[Vorschau] Etsy → Lexoffice ${label}${lines}`,
  created:           `Etsy → Lexoffice ${label}: ${r.file_name}${lines}`,
  regenerated:       `Etsy → Lexoffice ${label}: ${r.file_name} neu erzeugt${lines}`,
  existing:          `Etsy → Lexoffice ${label}: ${r.file_name} bereits erzeugt`
                       + (r.confirmed_at ? ' und importiert' : ' (erneut versendet)'),
  confirmed:         `Etsy → Lexoffice ${label}: Import bestätigt`,
  already_confirmed: `Etsy → Lexoffice ${label}: Import war bereits bestätigt`,
}[r.status] ?? `FEHLER Etsy → Lexoffice ${label}: keine Datei erzeugt`;

const attach = Boolean(r.csv) && (['preview', 'created', 'regenerated'].includes(r.status)
  || (r.status === 'existing' && !r.confirmed_at));
const fileName = r.status === 'preview'
  ? String(r.file_name).replace(/\.csv$/, '_VORSCHAU.csv')
  : r.file_name;

return [{
  json: {
    subject,
    text: r.report_text,
    has_file: attach,
    // Antwort für den Webhook (bei Schedule-Läufen nur im Execution-Log)
    response: {
      status:    r.status,
      ok:        r.ok,
      month:     r.month,
      file_name: fileName ?? null,
      errors:    r.errors ?? [],
      warnings:  r.warnings ?? [],
      lines:     r.lines ?? [],
      csv:       r.csv ?? null,
    },
  },
  ...(attach ? {
    binary: {
      csv: {
        data:     Buffer.from(r.csv, 'utf8').toString('base64'),
        mimeType: 'text/csv',
        fileName,
      },
    },
  } : {}),
}];
